CREATE TABLE IF NOT EXISTS season (id BIGINT NOT NULL AUTO_INCREMENT, season_key VARCHAR(32) NOT NULL, name VARCHAR(64) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_season_key(season_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS season_rule (id BIGINT NOT NULL AUTO_INCREMENT, season_id BIGINT NOT NULL, rule_name VARCHAR(64) NOT NULL, rule_text VARCHAR(255) NOT NULL, scope VARCHAR(16) NOT NULL, starts_at DATETIME NULL, ends_at DATETIME NULL, PRIMARY KEY(id), KEY idx_season_rule(season_id, scope)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_season_progress (id BIGINT NOT NULL AUTO_INCREMENT, season_id BIGINT NOT NULL, uid INT NOT NULL, xp INT NOT NULL DEFAULT 0, PRIMARY KEY(id), UNIQUE KEY uk_user_season(season_id, uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS season_task_log (id BIGINT NOT NULL AUTO_INCREMENT, season_id BIGINT NOT NULL, uid INT NOT NULL, source VARCHAR(32) NOT NULL, task_date DATE NOT NULL, xp INT NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_season_daily_source(season_id, uid, source, task_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS season_reward_log (id BIGINT NOT NULL AUTO_INCREMENT, season_id BIGINT NOT NULL, uid INT NOT NULL, reward_tier INT NOT NULL, reward_name VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_season_reward(season_id, uid, reward_tier)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
